E11.src_wrap:
public static function wrap( $args ) {
	$a = wp_parse_args( $args, array(
		'subject'    => '',
		'preheader'  => '',
		'body'       => '',
		'flow_class' => 'service',
		'email'      => '',
		'reason'     => '',
	) );
	return self::open( $a['subject'], $a['preheader'] )
		. $a['body']
		. self::close( $a['flow_class'], $a['email'], $a['reason'] );
}

E11.src_secondary:
public static function secondary( $links ) {
	$parts = array();
	foreach ( (array) $links as $label => $url ) {
		if ( ! $url ) { continue; }
		$parts[] = '<a href="' . esc_url( $url ) . '" style="color:' . self::C_ACCENT . ';">' . esc_html( $label ) . '</a>';
	}
	if ( ! $parts ) { return ''; }
	return '<tr><td style="font-size:14px;line-height:1.6;padding-bottom:20px;">' . implode( ' · ', $parts ) . '</td></tr>';
}

E11.src_button:
public static function button( $url, $label ) {
	if ( ! $url || ! $label ) { return ''; }
	return '<tr><td style="padding:6px 0 22px;">'
		. '<a href="' . esc_url( $url ) . '" '
		. 'style="background:' . self::C_ACCENT . ';color:#FFFFFF;text-decoration:none;'
		. 'padding:14px 26px;border-radius:8px;font-weight:600;font-size:15px;display:inline-block;">'
		. esc_html( $label ) . '</a></td></tr>';
}

E11.src_p:
public static function p( $html, $size = 15 ) {
	return '<tr><td style="font-size:' . (int) $size . 'px;line-height:1.65;padding-bottom:16px;">' . $html . '</td></tr>';
}
